def resample_linear(values, positions):
    if not values:
        return []
    n = len(values)
    result = []
    for pos in positions:
        if pos < 0 or pos > n - 1:
            # reject out-of-range positions by skipping
            continue
        idx = int(pos)
        if idx == pos:
            result.append(values[idx])
        else:
            if idx + 1 < n:
                alpha = pos - idx
                val = values[idx] + alpha * (values[idx+1] - values[idx])
                result.append(val)
            else:
                # pos is between last index and n-1, but not exceeding, so use last value
                result.append(values[idx])
    return result
